PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS workspaces(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,plan TEXT NOT NULL DEFAULT 'all',status TEXT NOT NULL DEFAULT 'trial',email_localpart TEXT,mail_enabled INTEGER DEFAULT 1,mail_invoices INTEGER DEFAULT 1,mail_reminders INTEGER DEFAULT 1,mail_receipts INTEGER DEFAULT 1,mail_offers INTEGER DEFAULT 1,mail_orders INTEGER DEFAULT 1,mail_proformas INTEGER DEFAULT 1,mail_credits INTEGER DEFAULT 1,weekly_report_enabled INTEGER DEFAULT 1,monthly_report_enabled INTEGER DEFAULT 1,last_weekly_report_at TEXT,last_monthly_report_at TEXT,ico TEXT,dic TEXT,street TEXT,city TEXT,zip TEXT,email TEXT,phone TEXT,bank_account TEXT,logo_path TEXT,onboarding_completed_at TEXT,timezone TEXT DEFAULT 'Europe/Prague',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id INTEGER NOT NULL,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'employee',permissions_json TEXT,active INTEGER NOT NULL DEFAULT 1,email_verified_at TEXT,email_verification_token_hash TEXT,email_verification_expires_at TEXT,last_login_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS subscriptions(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id INTEGER NOT NULL UNIQUE,plan TEXT NOT NULL,status TEXT NOT NULL,trial_ends_at TEXT,billing_interval TEXT DEFAULT 'month',free_until TEXT,stripe_customer_id TEXT,stripe_subscription_id TEXT,stripe_price_id TEXT,gopay_subscription_payment_id INTEGER,current_period_end TEXT,cancel_at_period_end INTEGER DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS customers(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id INTEGER NOT NULL,type TEXT NOT NULL DEFAULT 'company',company_name TEXT,first_name TEXT,last_name TEXT,ico TEXT,dic TEXT,street TEXT,city TEXT,zip TEXT,country TEXT DEFAULT 'Česká republika',delivery_street TEXT,delivery_city TEXT,delivery_zip TEXT,email TEXT,phone TEXT,web TEXT,note TEXT,active INTEGER DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS documents(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id INTEGER NOT NULL,doc_type TEXT NOT NULL,doc_number TEXT NOT NULL,variable_symbol TEXT,customer_id INTEGER,parent_document_id INTEGER,status TEXT DEFAULT 'draft',payment_status TEXT DEFAULT 'unpaid',issue_date TEXT,due_date TEXT,tax_date TEXT,notes TEXT,footer TEXT,payment_method TEXT DEFAULT 'bank_transfer',total_without_vat REAL DEFAULT 0,total_vat REAL DEFAULT 0,total_with_vat REAL DEFAULT 0,created_by INTEGER,public_token TEXT UNIQUE,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL,FOREIGN KEY(parent_document_id) REFERENCES documents(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS document_items(id INTEGER PRIMARY KEY AUTOINCREMENT,document_id INTEGER NOT NULL,name TEXT NOT NULL,description TEXT,quantity REAL DEFAULT 1,unit TEXT DEFAULT 'ks',unit_price REAL DEFAULT 0,vat_rate REAL DEFAULT 21,line_total REAL DEFAULT 0,warehouse_item_id INTEGER,FOREIGN KEY(document_id) REFERENCES documents(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id INTEGER NOT NULL,document_id INTEGER NOT NULL,amount REAL NOT NULL,paid_at TEXT,method TEXT,source TEXT,bank_transaction_id INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,FOREIGN KEY(document_id) REFERENCES documents(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS jobs(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id INTEGER NOT NULL,customer_id INTEGER,name TEXT NOT NULL,description TEXT,location TEXT,start_date TEXT,end_date TEXT,status TEXT DEFAULT 'planned',budget REAL DEFAULT 0,actual_cost REAL DEFAULT 0,notes TEXT,source_document_id INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL,FOREIGN KEY(source_document_id) REFERENCES documents(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS job_hours(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id INTEGER NOT NULL,job_id INTEGER NOT NULL,user_id INTEGER,hours REAL NOT NULL,rate REAL DEFAULT 0,work_date TEXT,note TEXT,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,FOREIGN KEY(job_id) REFERENCES jobs(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS job_materials(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id INTEGER NOT NULL,job_id INTEGER NOT NULL,product_id INTEGER NOT NULL,qty REAL NOT NULL,unit_cost REAL DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,FOREIGN KEY(job_id) REFERENCES jobs(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE RESTRICT);
CREATE TABLE IF NOT EXISTS expenses(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id INTEGER NOT NULL,supplier TEXT,expense_date TEXT,amount REAL DEFAULT 0,vat_amount REAL DEFAULT 0,category TEXT,document_number TEXT,receipt_path TEXT,note TEXT,job_id INTEGER,ocr_json TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,FOREIGN KEY(job_id) REFERENCES jobs(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id INTEGER NOT NULL,sku TEXT,name TEXT NOT NULL,unit TEXT DEFAULT 'ks',purchase_price REAL DEFAULT 0,sale_price REAL DEFAULT 0,vat_rate REAL DEFAULT 21,stock REAL DEFAULT 0,min_stock REAL DEFAULT 0,supplier TEXT,active INTEGER DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS stock_movements(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id INTEGER NOT NULL,product_id INTEGER NOT NULL,qty REAL NOT NULL,type TEXT,job_id INTEGER,note TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE,FOREIGN KEY(job_id) REFERENCES jobs(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS gopay_accounts(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id INTEGER NOT NULL UNIQUE,goid_encrypted TEXT NOT NULL,client_id_encrypted TEXT NOT NULL,client_secret_encrypted TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS bank_accounts(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id INTEGER NOT NULL,name TEXT NOT NULL,provider TEXT,external_id TEXT,token_encrypted TEXT,read_only INTEGER DEFAULT 1,active INTEGER DEFAULT 1,last_sync_at TEXT,last_error TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS bank_transactions(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id INTEGER NOT NULL,bank_account_id INTEGER,booked_at TEXT,amount REAL,currency TEXT DEFAULT 'CZK',counterparty TEXT,account_number TEXT,variable_symbol TEXT,constant_symbol TEXT,specific_symbol TEXT,reference TEXT,message TEXT,status TEXT DEFAULT 'unmatched',match_score REAL DEFAULT 0,matched_document_id INTEGER,matched_at TEXT,external_id TEXT,raw_json TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,FOREIGN KEY(bank_account_id) REFERENCES bank_accounts(id) ON DELETE SET NULL,FOREIGN KEY(matched_document_id) REFERENCES documents(id) ON DELETE SET NULL);
CREATE UNIQUE INDEX IF NOT EXISTS uq_bank_tx_external ON bank_transactions(workspace_id,external_id);
CREATE TABLE IF NOT EXISTS calendar_events(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id INTEGER NOT NULL,title TEXT,start_at TEXT,end_at TEXT,type TEXT DEFAULT 'event',note TEXT,customer_id INTEGER,job_id INTEGER,user_id INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL,FOREIGN KEY(job_id) REFERENCES jobs(id) ON DELETE SET NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS documents_files(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id INTEGER NOT NULL,entity_type TEXT,entity_id INTEGER,file_name TEXT,storage_path TEXT,mime_type TEXT,size INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS automation_rules(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id INTEGER NOT NULL,name TEXT,trigger_type TEXT,action_type TEXT,config_json TEXT,active INTEGER DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS audit_log(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id INTEGER,user_id INTEGER,action TEXT,entity_type TEXT,entity_id INTEGER,metadata_json TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS api_keys(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL,name TEXT,key_hash TEXT UNIQUE,last_used_at TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS email_queue(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id INTEGER NOT NULL,to_email TEXT,subject TEXT,body TEXT,attachment_path TEXT,action_url TEXT,status TEXT DEFAULT 'queued',scheduled_at TEXT,attempts INTEGER DEFAULT 0,last_error TEXT,html_body TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS email_messages(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id INTEGER NOT NULL,customer_id INTEGER,document_id INTEGER,direction TEXT NOT NULL DEFAULT 'inbound',from_email TEXT,to_email TEXT,subject TEXT,body TEXT,html_body TEXT,message_id TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL,FOREIGN KEY(document_id) REFERENCES documents(id) ON DELETE SET NULL);
CREATE INDEX IF NOT EXISTS idx_email_messages_workspace ON email_messages(workspace_id,created_at);
CREATE TABLE IF NOT EXISTS recurring_invoices(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id INTEGER NOT NULL,customer_id INTEGER,interval_type TEXT,interval_value INTEGER DEFAULT 1,next_run TEXT,active INTEGER DEFAULT 1,send_email INTEGER DEFAULT 1,template_json TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS tax_profiles(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id INTEGER UNIQUE,vat_payer INTEGER DEFAULT 0,income_tax_method TEXT DEFAULT 'actual',social_rate REAL DEFAULT 0,health_rate REAL DEFAULT 0,flat_regime INTEGER DEFAULT 0,flat_monthly_tax REAL DEFAULT 0,flat_social_monthly REAL DEFAULT 0,flat_health_monthly REAL DEFAULT 0,tax_credit REAL DEFAULT 0,expense_lump_rate REAL DEFAULT 0.6,year INTEGER DEFAULT 2026,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS automation_runs(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id INTEGER,rule_id INTEGER,status TEXT,message TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS webhook_events(id INTEGER PRIMARY KEY AUTOINCREMENT,provider TEXT,event_id TEXT,payload_json TEXT,processed_at TEXT,UNIQUE(provider,event_id));
CREATE INDEX IF NOT EXISTS idx_customer_workspace ON customers(workspace_id);CREATE INDEX IF NOT EXISTS idx_documents_workspace ON documents(workspace_id);CREATE INDEX IF NOT EXISTS idx_bank_workspace ON bank_transactions(workspace_id);CREATE INDEX IF NOT EXISTS idx_jobs_workspace ON jobs(workspace_id);CREATE INDEX IF NOT EXISTS idx_expenses_workspace ON expenses(workspace_id);CREATE INDEX IF NOT EXISTS idx_events_workspace ON calendar_events(workspace_id);CREATE INDEX IF NOT EXISTS idx_email_queue ON email_queue(status,scheduled_at);

CREATE TABLE IF NOT EXISTS bank_connections(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id INTEGER NOT NULL,provider TEXT NOT NULL,customer_ref TEXT,connection_ref TEXT,account_ref TEXT,account_name TEXT,iban TEXT,currency TEXT,status TEXT DEFAULT 'active',last_sync_at TEXT,last_error TEXT,meta_json TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS tasks(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id INTEGER NOT NULL,title TEXT NOT NULL,description TEXT,due_at TEXT,priority TEXT DEFAULT 'normal',status TEXT DEFAULT 'open',customer_id INTEGER,job_id INTEGER,assigned_user_id INTEGER,completed_at TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL,FOREIGN KEY(job_id) REFERENCES jobs(id) ON DELETE SET NULL,FOREIGN KEY(assigned_user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS customer_communications(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id INTEGER NOT NULL,customer_id INTEGER NOT NULL,channel TEXT DEFAULT 'note',direction TEXT DEFAULT 'internal',subject TEXT,message TEXT,created_by INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE,FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS ai_actions(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id INTEGER NOT NULL,user_id INTEGER,action_type TEXT NOT NULL,payload_json TEXT NOT NULL,status TEXT DEFAULT 'pending',result_json TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,executed_at TEXT,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS reminder_log(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id INTEGER NOT NULL,document_id INTEGER NOT NULL,days_offset INTEGER NOT NULL,sent_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(workspace_id,document_id,days_offset),FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,FOREIGN KEY(document_id) REFERENCES documents(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_tasks_workspace ON tasks(workspace_id,status,due_at);
CREATE INDEX IF NOT EXISTS idx_files_workspace ON documents_files(workspace_id,created_at);

CREATE TABLE IF NOT EXISTS document_series(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id INTEGER NOT NULL,doc_type TEXT NOT NULL,prefix TEXT NOT NULL,next_number INTEGER NOT NULL DEFAULT 1,UNIQUE(workspace_id,doc_type),FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS custom_roles(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id INTEGER NOT NULL,name TEXT NOT NULL,permissions_json TEXT NOT NULL DEFAULT '{}',created_at TEXT DEFAULT CURRENT_TIMESTAMP,UNIQUE(workspace_id,name),FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS inventory_counts(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id INTEGER NOT NULL,product_id INTEGER NOT NULL,expected_stock REAL NOT NULL,counted_stock REAL NOT NULL,difference REAL NOT NULL,note TEXT,created_by INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS login_attempts(id INTEGER PRIMARY KEY AUTOINCREMENT,ip_hash TEXT NOT NULL,email_hash TEXT NOT NULL,attempted_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_login_attempts ON login_attempts(ip_hash,attempted_at);
CREATE TABLE IF NOT EXISTS outgoing_webhooks(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id INTEGER NOT NULL,url TEXT NOT NULL,secret TEXT,events_json TEXT NOT NULL DEFAULT '["*"]',active INTEGER DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS gdpr_requests(id INTEGER PRIMARY KEY AUTOINCREMENT,workspace_id INTEGER NOT NULL,user_id INTEGER,request_type TEXT NOT NULL,status TEXT DEFAULT 'requested',created_at TEXT DEFAULT CURRENT_TIMESTAMP,completed_at TEXT,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE);

CREATE TABLE IF NOT EXISTS saas_settings(id INTEGER PRIMARY KEY CHECK(id=1),monthly_price_czk REAL NOT NULL DEFAULT 300,yearly_price_czk REAL NOT NULL DEFAULT 3240,trial_days INTEGER NOT NULL DEFAULT 14,mail_domain TEXT NOT NULL DEFAULT 'byznio.cz',last_automatic_backup_at TEXT,mail_enabled_default INTEGER NOT NULL DEFAULT 1,updated_at TEXT DEFAULT CURRENT_TIMESTAMP); INSERT OR IGNORE INTO saas_settings(id) VALUES(1);

CREATE TABLE IF NOT EXISTS gopay_subscription_payments(id INTEGER PRIMARY KEY AUTOINCREMENT,payment_id INTEGER NOT NULL UNIQUE,workspace_id INTEGER NOT NULL,parent_payment_id INTEGER,state TEXT,amount REAL DEFAULT 0,created_at TEXT DEFAULT CURRENT_TIMESTAMP,paid_at TEXT,FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE);
